","export class CardService {
 constructor() {
 this.assetTable = 'alm_asset';
 this.modelTable = 'cmdb_model';
 }

 async getUserCards() {
 try {
 // Get assets assigned to current user with model information
 const response = await fetch(
 `/api/now/table/${this.assetTable}?sysparm_query=assigned_to.user_name=javascript:gs.getUserName()&sysparm_display_value=all&sysparm_fields=sys_id,asset_tag,model,model.name,model.short_description,model.description,model.picture,install_date,cost,substatus`,
 {
 headers: {
 "Accept": "application/json",
 "X-UserToken": window.g_ck
 }
 }
 );

 if (!response.ok) {
 const error = await response.json();
 throw new Error(error.error?.message || 'Failed to fetch user cards');
 }

 const data = await response.json();
 return data.result || [];
 } catch (error) {
 console.error('Error fetching user cards:', error);
 throw error;
 }
 }

 async getCardDetails(modelSysId) {
 try {
 const response = await fetch(
 `/api/now/table/${this.modelTable}/${modelSysId}?sysparm_display_value=all`,
 {
 headers: {
 "Accept": "application/json",
 "X-UserToken": window.g_ck
 }
 }
 );

 if (!response.ok) {
 const error = await response.json();
 throw new Error(error.error?.message || 'Failed to fetch card details');
 }

 const data = await response.json();
 return data.result;
 } catch (error) {
 console.error('Error fetching card details:', error);
 throw error;
 }
 }
}","export const display = (field) => {
 if (typeof field === 'string') {
 return field;
 }
 return field?.display_value || '';
};

export const value = (field) => {
 if (typeof field === 'string') {
 return field;
 }
 return field?.value || '';
};","export default function mPi(r,e="style"){if(!(!r||typeof window>"u")){if(e==="style"){let s=document.createElement("style");s.setAttribute("type","text/css"),s.innerHTML=r,document.head.appendChild(s)}else if(e==="link"){let s=document.createElement("link");s.setAttribute("rel","stylesheet"),s.setAttribute("href",r),document.head.appendChild(s)}return r}}","import React from 'react';
import { display, value } from '../utils/fields.js';
import './CardItem.css';

export default function CardItem({ card }) {
 const modelName = display(card.model?.name || card.model);
 const modelDescription = display(card.model?.short_description || '');
 const assetTag = display(card.asset_tag);
 const installDate = display(card.install_date);
 const substatus = display(card.substatus);
 const picture = display(card.model?.picture);

 const formatDate = (dateString) => {
 if (!dateString) return '';
 try {
 return new Date(dateString).toLocaleDateString();
 } catch (e) {
 return dateString;
 }
 };

 return (
 <div className="card-item">
 <div className="card-header">
 {picture && (
 <img 
 src={`/sys_attachment.do?sys_id=${picture}`} 
 alt={modelName}
 className="card-image"
 onError={(e) => {
 e.target.style.display = 'none';
 }}
 />
 )}
 <div className="card-title-section">
 <h3 className="card-title">{modelName}</h3>
 {assetTag && <span className="asset-tag">#{assetTag}</span>}
 </div>
 </div>

 <div className="card-content">
 {modelDescription && (
 <p className="card-description">{modelDescription}</p>
