 background: #ffffff;
 border: 1px solid #e0e0e0;
 border-radius: 12px;
 padding: 20px;
 margin: 16px;
 box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
 transition: transform 0.2s ease, box-shadow 0.2s ease;
 max-width: 320px;
 min-height: 280px;
}

.card-item:hover {
 transform: translateY(-2px);
 box-shadow: 0 4px 16px rgba(0, 0, 0, 0.15);
}

.card-header {
 display: flex;
 align-items: flex-start;
 margin-bottom: 16px;
 gap: 12px;
}

.card-image {
 width: 48px;
 height: 48px;
 border-radius: 8px;
 object-fit: cover;
 border: 1px solid #e0e0e0;
 flex-shrink: 0;
}

.card-title-section {
 flex: 1;
 min-width: 0;
}

.card-title {
 font-size: 18px;
 font-weight: 600;
 color: #333;
 margin: 0 0 4px 0;
 line-height: 1.3;
 word-wrap: break-word;
}

.asset-tag {
 background: #f0f8ff;
 color: #0066cc;
 font-size: 12px;
 font-weight: 500;
 padding: 2px 8px;
 border-radius: 12px;
 border: 1px solid #cce7ff;
}

.card-content {
 flex: 1;
}

.card-description {
 color: #666;
 font-size: 14px;
 line-height: 1.5;
 margin: 0 0 16px 0;
 word-wrap: break-word;
}

.card-details {
 display: flex;
 flex-direction: column;
 gap: 8px;
}

.detail-item {
 display: flex;
 justify-content: space-between;
 align-items: center;
 font-size: 13px;
}

.detail-label {
 color: #777;
 font-weight: 500;
}

.detail-value {
 color: #333;
 font-weight: 400;
}

.status-badge {
 padding: 3px 8px;
 border-radius: 12px;
 font-size: 11px;
 font-weight: 600;
 text-transform: uppercase;
 letter-spacing: 0.5px;
}

.status-available {
 background: #e6f7e6;
 color: #2d7d32;
 border: 1px solid #c3e6c3;
}

.status-in-use {
 background: #fff3e0;
 color: #ef6c00;
 border: 1px solid #ffcc80;
}

.status-retired {
 background: #f5f5f5;
 color: #757575;
 border: 1px solid #e0e0e0;
}

/* Responsive design */
@media (max-width: 768px) {
 .card-item {
 margin: 8px 0;
 max-width: 100%;
 }

 .card-title {
 font-size: 16px;
 }
}",".app-container {
 max-width: 1200px;
 margin: 0 auto;
 padding: 24px;
 font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
 background: #f8f9fa;
 min-height: 100vh;
}

.header {
 display: flex;
 align-items: center;
 justify-content: space-between;
 margin-bottom: 32px;
 flex-wrap: wrap;
 gap: 16px;
}

.page-title {
 font-size: 28px;
 font-weight: 700;
 color: #333;
 margin: 0;
 flex: 1;
 min-width: 200px;
}

.user-welcome {
 color: #666;
 font-size: 14px;
 margin: 0;
 font-weight: 500;
}

.refresh-button {
 background: #0066cc;
 color: white;
 border: none;
 padding: 8px 16px;
 border-radius: 6px;
 cursor: pointer;
 font-size: 14px;
 font-weight: 500;
 display: flex;
 align-items: center;
 gap: 6px;
 transition: background-color 0.2s ease;
}

.refresh-button:hover {
 background: #0052a3;
}

.refresh-button:active {
 transform: translateY(1px);
}

.refresh-icon {
 font-size: 16px;
 display: inline-block;
 transition: transform 0.3s ease;
}

.refresh-button:hover .refresh-icon {
 transform: rotate(180deg);
}

.loading-container {
 display: flex;
 flex-direction: column;
 align-items: center;
 justify-content: center;
 min-height: 400px;
 color: #666;
}

.loading-spinner {
 width: 40px;
 height: 40px;
 border: 3px solid #f3f3f3;
 border-top: 3px solid #0066cc;
 border-radius: 50%;
 animation: spin 1s linear infinite;
 margin-bottom: 16px;
}

@keyframes spin {
 0% { transform: rotate(0deg); }
 100% { transform: rotate(360deg); }
}

.error-container {
 text-align: center;
 padding: 40px 20px;
 background: white;
 border-radius: 8px;
 border: 1px solid #ffcccc;
 color: #d32f2f;
}

.error-container h2 {
 color: #d32f2f;
 margin: 0 0 12px 0;
}

.error-message {
 margin-bottom: 20px;
 color: #666;
}

.retry-button {
 background: #d32f2f;
 color: white;
 border: none;
 padding: 10px 20px;
 border-radius: 6px;
 cursor: pointer;
 font-size: 14px;
 transition: background-color 0.2s ease;
}

.retry-button:hover {
 background: #b71c1c;
}

.empty-state {
 text-align: center;
 padding: 80px 20px;
 background: white;
 border-radius: 12px;
 border: 1px solid #e0e0e0;
 color: #666;
}

.empty-icon {
 font-size: 64px;
 margin-bottom: 20px;
 opacity: 0.6;
}

.empty-state h2 {
 color: #333;
 margin: 0 0 12px 0;
 font-size: 24px;
}

.empty-state p {
 margin: 8px 0;
 font-size: 16px;
 line-height: 1.5;
}

.cards-summary {
 margin-bottom: 24px;
 padding: 12px 0;
 border-bottom: 1px solid #e0e0e0;
}

.card-count {
 color: #666;
 font-size: 14px;
 font-weight: 500;
}

.cards-grid {
 display: grid;
 grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
 gap: 0;
 margin: -16px;
}

/* Responsive adjustments */
@media (max-width: 768px) {
 .app-container {
 padding: 16px;
 }

 .header {
 flex-direction: column;
 align-items: flex-start;
 gap: 12px;
 }

 .page-title {
 font-size: 24px;
 min-width: auto;
 }

 .cards-grid {
 grid-template-columns: 1fr;
 gap: 16px;
 margin: 0;
 }

 .user-welcome {
 align-self: flex-start;
 }

 .refresh-button {
 align-self: flex-end;
 }
}

@media (max-width: 480px) {
 .page-title {
 font-size: 20px;
 }

 .empty-state {
 padding: 40px 16px;
 }

 .empty-icon {
 font-size: 48px;
 }
