 const [loading, setLoading] = useState(true);
 const [error, setError] = useState(null);
 const [currentUser, setCurrentUser] = useState('');

 const cardService = new CardService();

 useEffect(() => {
 loadUserCards();
 getCurrentUser();
 }, []);

 const getCurrentUser = async () => {
 try {
 const response = await fetch('/api/now/table/sys_user?sysparm_query=user_name=javascript:gs.getUserName()&sysparm_fields=name,user_name&sysparm_display_value=all&sysparm_limit=1', {
 headers: {
 "Accept": "application/json",
 "X-UserToken": window.g_ck
 }
 });

 if (response.ok) {
 const data = await response.json();
 if (data.result && data.result.length > 0) {
 setCurrentUser(data.result[0].name?.display_value || data.result[0].user_name?.display_value || '');
 }
 }
 } catch (err) {
 console.error('Error fetching current user:', err);
 }
 };

 const loadUserCards = async () => {
 try {
 setLoading(true);
 setError(null);
 const userCards = await cardService.getUserCards();
 setCards(userCards);
 } catch (err) {
 setError(err.message || 'Failed to load cards');
 console.error('Error loading user cards:', err);
 } finally {
 setLoading(false);
 }
 };

 const handleRefresh = () => {
 loadUserCards();
 };

 if (loading) {
 return (
 <div className="app-container">
 <div className="loading-container">
 <div className="loading-spinner"></div>
 <p>Loading your cards...</p>
 </div>
 </div>
 );
 }

 if (error) {
 return (
 <div className="app-container">
 <div className="error-container">
 <h2>Unable to Load Cards</h2>
 <p className="error-message">{error}</p>
 <button onClick={handleRefresh} className="retry-button">
 Try Again
 </button>
 </div>
 </div>
 );
 }

 return (
 <div className="app-container">
 <div className="header">
 <h1 className="page-title">My Visual Cards</h1>
 {currentUser && (
 <p className="user-welcome">Welcome, {currentUser}</p>
 )}
 <button onClick={handleRefresh} className="refresh-button" title="Refresh Cards">
 <span className="refresh-icon">⟲</span> Refresh
 </button>
 </div>

 {cards.length === 0 ? (
 <div className="empty-state">
 <div className="empty-icon">🎴</div>
 <h2>No Cards Found</h2>
 <p>You don't have any visual cards assigned to you yet.</p>
 <p>Contact your administrator if you believe this is an error.</p>
 </div>
 ) : (
 <div>
 <div className="cards-summary">
 <span className="card-count">
 {cards.length} card{cards.length !== 1 ? 's' : ''} assigned
 </span>
 </div>

 <div className="cards-grid">
 {cards.map((card) => (
 <CardItem 
 key={card.sys_id?.value || card.sys_id} 
 card={card} 
 />
 ))}
 </div>
 </div>
 )}
 </div>
 );
